CREATE TABLE stored_files(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_id uuid REFERENCES documents(id),filename text NOT NULL,mime text NOT NULL,data bytea NOT NULL,sha256 text NOT NULL,size integer NOT NULL CHECK(size>0 AND size<=5242880),created_by uuid NOT NULL REFERENCES public.users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX file_once_document ON stored_files(document_id,sha256) WHERE document_id IS NOT NULL;
CREATE UNIQUE INDEX file_once_source ON stored_files(sha256) WHERE document_id IS NULL;
CREATE TRIGGER immutable_stored_file BEFORE UPDATE OR DELETE ON stored_files FOR EACH ROW EXECUTE FUNCTION guard_immutable();
CREATE TABLE file_extractions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),file_id uuid NOT NULL REFERENCES stored_files(id),engine text NOT NULL,text text NOT NULL,fields jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE import_batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),file_id uuid NOT NULL REFERENCES stored_files(id),kind text NOT NULL CHECK(kind IN ('invoice','purchase','product')),mapping jsonb NOT NULL,mapping_hash text NOT NULL,created_by uuid NOT NULL REFERENCES public.users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(file_id,kind,mapping_hash));
CREATE TABLE import_items(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,batch_id uuid NOT NULL REFERENCES import_batches(id),row_number integer NOT NULL,source_key text NOT NULL,payload jsonb NOT NULL,errors jsonb NOT NULL DEFAULT '[]',status text NOT NULL CHECK(status IN ('ready','error','imported','duplicate')),result_id uuid,UNIQUE(batch_id,row_number));
CREATE TABLE import_results(source_key text PRIMARY KEY,result_id uuid NOT NULL,batch_id uuid NOT NULL REFERENCES import_batches(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER immutable_import_results BEFORE UPDATE OR DELETE ON import_results FOR EACH ROW EXECUTE FUNCTION guard_immutable();
ALTER TABLE documents ADD COLUMN buyer_fields jsonb NOT NULL DEFAULT '{}';
CREATE TABLE buyer_policies(tax_id text PRIMARY KEY,name text NOT NULL,required_fields text[] NOT NULL DEFAULT '{}',severity text NOT NULL CHECK(severity IN ('warning','block')),notes text NOT NULL DEFAULT '',version integer NOT NULL DEFAULT 1);
CREATE TABLE buyer_policy_versions(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tax_id text NOT NULL,version integer NOT NULL,data jsonb NOT NULL,created_by uuid NOT NULL REFERENCES public.users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tax_id,version));
CREATE TRIGGER immutable_buyer_policy_versions BEFORE UPDATE OR DELETE ON buyer_policy_versions FOR EACH ROW EXECUTE FUNCTION guard_immutable();
CREATE TABLE issued_requirement_checks(document_id uuid PRIMARY KEY REFERENCES documents(id),report jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER immutable_issued_requirement_checks BEFORE UPDATE OR DELETE ON issued_requirement_checks FOR EACH ROW EXECUTE FUNCTION guard_immutable();
-- Append the field without changing the established order of the balance view columns.
CREATE OR REPLACE VIEW document_balances AS SELECT d.id,d.kind,d.status,d.number,d.version,d.date,d.due_date,d.party,d.reference,d.notes,d.retention_rate,d.lines,d.net,d.tax,d.retention,d.total,d.calculation_version,d.company_snapshot,d.original_id,d.converted_id,d.created_by,d.created_at,d.issued_at,d.operation_date,d.registration_date,d.series_code,d.credit_side,COALESCE(p.amount,0)+COALESCE(c.amount,0)+COALESCE(f.amount,0) AS settled,d.total-COALESCE(p.amount,0)-COALESCE(c.amount,0)-COALESCE(f.amount,0) AS balance,d.buyer_fields FROM documents d LEFT JOIN LATERAL (SELECT sum(amount) AS amount FROM payments WHERE document_id=d.id AND reversed_at IS NULL) p ON true LEFT JOIN LATERAL (SELECT sum(amount) AS amount FROM credit_applications WHERE credit_id=d.id OR invoice_id=d.id) c ON true LEFT JOIN LATERAL (SELECT sum(amount) AS amount FROM fund_applications WHERE document_id=d.id AND kind='apply') f ON true;
